mapper.select:
SELECT id, book_id, chapter_name, chapter_num, word_count, audit_status, reject_reason, create_time
FROM book_chapter
WHERE id = #{id}

SELECT MAX(chapter_num)
FROM book_chapter
WHERE book_id = #{bookId}

SELECT COALESCE(SUM(word_count), 0)
FROM book_chapter
WHERE book_id = #{bookId}

mapper.update:
UPDATE book_chapter
SET audit_status = #{auditStatus},
    reject_reason = #{rejectReason}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM book_chapter
WHERE audit_status = #{auditStatus}

mapper.update:
UPDATE book_chapter
SET word_count = #{wordCount}
WHERE id = #{id}
